// Replaces the service worker generated by react-scripts (see "postbuild" in package.json).
//
// The old worker was registered for the whole pyozer.github.io origin and answered every navigation
// with this app's index.html, which hid the project sites hosted under /<repo>/ (404 page of the app).
// Browsers that already installed it fetch this file when they next visit the site: it activates
// immediately, deletes the caches, unregisters itself and reloads the open tabs.

self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach((client) => client.navigate(client.url));
    })()
  );
});
